import { defineConfig } from "vite";
import { deploymentPlugin, fileRouter } from "@kasperrt/smolter/react/vite";

export default defineConfig({
  plugins: [fileRouter(), deploymentPlugin()],
});

// Preact uses the same exports from /preact/vite.
// With applicationPlugins(), add deploymentPlugin() beside it.

import deployment from "virtual:smolter/deployment";
import { createDataRouter } from "@kasperrt/smolter/react";
import { watchDeployment } from "@kasperrt/smolter/react/client";

const router = createDataRouter(routes, { browser: true });
watchDeployment(router, deployment);

// Preact application integration:
const router = await mountApplication(routes, root, { deployment });

app.get("/smolter-manifest.json", (_request, response) => {
  response.set("Cache-Control", "no-store");
  response.sendFile(path.resolve("dist/client/smolter-manifest.json"));
});

app.use("/assets", express.static("dist/client/assets", {
  immutable: true,
  maxAge: "1y",
}));

watchDeployment(router, deployment && {
  ...deployment,
  timeout: 1500,
  reload: (destination) => {
    if (confirm("A new version is available. Reload?")) {
      location.assign(destination.href);
    }
  },
});

declare module "virtual:smolter/deployment" {
  const deployment: import("@kasperrt/smolter/preact/client").DeploymentOptions | null;
  export default deployment;
}
